-- Prior project schema, without user data. Used only to verify the cutover.
CREATE TABLE UGM_ROUTINES (
                    ID_ROUTINE TEXT PRIMARY KEY, NM_ROUTINE TEXT NOT NULL,
                    DS_ROUTINE TEXT NOT NULL, PROMPT_KEY TEXT NOT NULL,
                    LAYOUT_KEY TEXT NOT NULL, CONFIG_JSON TEXT NOT NULL DEFAULT '{}',
                    FL_ACTIVE INTEGER NOT NULL DEFAULT 1, DISPLAY_ORDER INTEGER NOT NULL DEFAULT 0);

CREATE TABLE UGM_ROUTINE_ACTIVITIES (
        ID_ACTIVITY TEXT PRIMARY KEY,
        ID_ROUTINE TEXT NOT NULL REFERENCES UGM_ROUTINES(ID_ROUTINE),
        NM_ACTIVITY TEXT NOT NULL, DS_ACTIVITY TEXT NOT NULL DEFAULT '',
        PROMPT_KEY TEXT NOT NULL, CONFIG_JSON TEXT NOT NULL DEFAULT '{}',
        FL_ACTIVE INTEGER NOT NULL DEFAULT 1 CHECK(FL_ACTIVE IN (0,1)),
        DISPLAY_ORDER INTEGER NOT NULL DEFAULT 0,
        UNIQUE(ID_ROUTINE,ID_ACTIVITY));

CREATE TABLE UGM_ROUTINE_TOOLS (
                    ID_ROUTINE TEXT NOT NULL REFERENCES UGM_ROUTINES(ID_ROUTINE),
                    NM_TOOL TEXT NOT NULL, HANDLER_KEY TEXT NOT NULL,
                    INPUT_SCHEMA_JSON TEXT NOT NULL, CONFIG_JSON TEXT NOT NULL DEFAULT '{}',
                    REVIEW_POLICY TEXT NOT NULL CHECK (REVIEW_POLICY IN ('AUTO','REVIEW','CONFIRM')),
                    FL_ACTIVE INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(ID_ROUTINE,NM_TOOL));

CREATE TABLE UGM_ROUTINE_ACTIVITY_TOOLS (
        ID_ACTIVITY TEXT NOT NULL, ID_ROUTINE TEXT NOT NULL, NM_TOOL TEXT NOT NULL,
        PRIMARY KEY(ID_ACTIVITY,NM_TOOL),
        FOREIGN KEY(ID_ROUTINE,ID_ACTIVITY) REFERENCES UGM_ROUTINE_ACTIVITIES(ID_ROUTINE,ID_ACTIVITY),
        FOREIGN KEY(ID_ROUTINE,NM_TOOL) REFERENCES UGM_ROUTINE_TOOLS(ID_ROUTINE,NM_TOOL));

CREATE TABLE UGM_ROUTINE_SCHEDULE (
                    ID_STEP TEXT PRIMARY KEY, ID_ROUTINE TEXT NOT NULL REFERENCES UGM_ROUTINES(ID_ROUTINE),
                    NM_STEP TEXT NOT NULL, DEADLINE_TIME TEXT,
                    RECURRENCE TEXT NOT NULL CHECK(RECURRENCE IN ('DAILY','WEEKDAYS','MANUAL')),
                    COMPLETION_ACTION TEXT, COMPLETION_CONFIG_JSON TEXT NOT NULL DEFAULT '{}',
                    FL_ACTIVE INTEGER NOT NULL DEFAULT 1, DISPLAY_ORDER INTEGER NOT NULL DEFAULT 0, ID_ACTIVITY TEXT REFERENCES UGM_ROUTINE_ACTIVITIES(ID_ACTIVITY));

CREATE TABLE UGM_ROUTINE_EXECUTIONS (
                    ID_EXECUTION INTEGER PRIMARY KEY AUTOINCREMENT,
                    ID_ROUTINE TEXT NOT NULL REFERENCES UGM_ROUTINES(ID_ROUTINE),
                    ID_STEP TEXT REFERENCES UGM_ROUTINE_SCHEDULE(ID_STEP), DT_REF TEXT NOT NULL,
                    USERNAME TEXT NOT NULL, NM_ACTION TEXT NOT NULL, TS_REQUEST TEXT NOT NULL,
                    TS_EXECUTION TEXT, STATUS TEXT NOT NULL CHECK(STATUS IN
                    ('PENDING_REVIEW','EXECUTING','SUCCESS','FAILED','CANCELLED')),
                    INPUT_JSON TEXT NOT NULL, RESULT_JSON TEXT, ERROR_MESSAGE TEXT, ID_ACTIVITY TEXT REFERENCES UGM_ROUTINE_ACTIVITIES(ID_ACTIVITY));

CREATE TABLE "UGM_ROUTINE_CHAT" (
        ID_MESSAGE INTEGER PRIMARY KEY AUTOINCREMENT,
        ID_ROUTINE TEXT NOT NULL REFERENCES UGM_ROUTINES(ID_ROUTINE),
        USERNAME TEXT NOT NULL, DT_REF TEXT NOT NULL, TS_MESSAGE TEXT NOT NULL,
        TS_RESPONSE TEXT, USER_MESSAGE TEXT NOT NULL DEFAULT '',
        ASSISTANT_MESSAGE TEXT NOT NULL DEFAULT '', STATUS TEXT NOT NULL DEFAULT 'COMPLETED',
        ID_EXECUTION INTEGER, ID_ACTIVITY TEXT REFERENCES UGM_ROUTINE_ACTIVITIES(ID_ACTIVITY));

CREATE TABLE UGM_ROUTINE_ACTIVITY_COMPLETIONS (
        ID_ACTIVITY TEXT NOT NULL REFERENCES UGM_ROUTINE_ACTIVITIES(ID_ACTIVITY),
        DT_REF TEXT NOT NULL,
        ID_EXECUTION INTEGER NOT NULL UNIQUE REFERENCES UGM_ROUTINE_EXECUTIONS(ID_EXECUTION),
        TS_COMPLETED TEXT NOT NULL,
        PRIMARY KEY(ID_ACTIVITY,DT_REF));
